import '../../../../core/network/authenticated_api_client.dart';import '../../domain/admin_console.dart';import '../../domain/admin_console_repository.dart';
class ApiAdminConsoleRepository implements AdminConsoleRepository{ApiAdminConsoleRepository(this._client);final AuthenticatedApiClient _client;
 @override Future<AdminOverview> overview()async{final response=await _client.get<Map<String,dynamic>>('users/overview');final data=response.data??const{};final users=data['users'],roles=data['roles'],permissions=data['permissions'];return AdminOverview(
  users:users is List?users.whereType<Map<String,dynamic>>().map((item)=>ManagedUser(id:item['id'] as String,email:item['email'] as String,fullName:item['fullName'] as String? ?? item['email'] as String,status:item['status'] as String,roles:(item['roles'] as List? ?? const[]).whereType<String>().toList())).toList():const[],
  roles:roles is List?roles.whereType<Map<String,dynamic>>().map((item)=>ManagedRole(code:item['code'] as String,name:item['name'] as String,permissions:(item['permissions'] as List? ?? const[]).whereType<String>().toList())).toList():const[],
  permissions:permissions is List?permissions.whereType<Map<String,dynamic>>().map((item)=>item['code'] as String).toList():const[]);}
 @override Future<void> updateStatus(String id,String status,{String? reason})async{await _client.patch<Map<String,dynamic>>('users/$id/status',data:{'status':status,'reason':reason});}
 @override Future<void> updateRoles(String id,List<String> roles)async{await _client.patch<Map<String,dynamic>>('users/$id/roles',data:{'roleCodes':roles});}
 @override Future<List<SystemSetting>> settings()async{final response=await _client.get<Map<String,dynamic>>('administration/system-settings');final items=response.data?['items'];return items is List?items.whereType<Map<String,dynamic>>().map((item)=>SystemSetting(key:item['key'] as String,value:item['value'],description:item['description'] as String?)).toList():const[];}
 @override Future<void> updateSetting(String key,Object? value,{String? description})async{await _client.put<Map<String,dynamic>>('administration/system-settings/$key',data:{'value':value,'description':description});}}
